/* SkyShield AI: offline accounts + risk engine (ported from our C program, RainReady 2.0) */
const $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)];
const ROOT = document.body.dataset.root || '';
const PAGE = document.body.dataset.page || 'home';

/* ---------- Storage (works offline; falls back to memory) ---------- */
const mem = {};
const store = (area) => ({
  get(k, d) { try { const v = window[area].getItem(k); return v ? JSON.parse(v) : d; } catch (e) { return k in mem ? mem[k] : d; } },
  set(k, v) { try { window[area].setItem(k, JSON.stringify(v)); } catch (e) { mem[k] = v; } },
  del(k) { try { window[area].removeItem(k); } catch (e) { delete mem[k]; } }
});
const L = store('localStorage'), S = store('sessionStorage');
const hash = s => { let h = 5381; for (const c of s) h = ((h << 5) + h + c.charCodeAt(0)) >>> 0; return 'h' + h; };
const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const me = () => S.get('ss_sess', null) || L.get('ss_sess', null);
const msg = (type, text) => { const m = $('#msg'); if (m) m.innerHTML = '<div class="alert alert-' + type + ' py-2">' + esc(text) + '</div>'; };
const goDash = () => { location.href = ROOT + 'pages/dashboard.html'; };
const goHome = () => { location.href = ROOT + 'index.html'; };
function logout() { S.del('ss_sess'); L.del('ss_sess'); goHome(); }

let tt;function toast(t,type){const el=$('#toast');if(!el)return;el.className='alert alert-'+(type||'dark')+' shadow mb-0 py-2';el.textContent=t;el.style.display='block';clearTimeout(tt);tt=setTimeout(()=>el.style.display='none',2800)}

/* ---------- Shared: navbar state + logout buttons ---------- */
const user = me();
if (user) {
  $$('.uFull').forEach(e => e.textContent = user.name);
  $$('.uMail').forEach(e => e.textContent = user.email);
  $$('.uName').forEach(e => e.textContent = user.name.split(' ')[0]);
}
$$('.auth-in').forEach(e => e.classList.toggle('d-none', !user));
$$('.auth-out').forEach(e => e.classList.toggle('d-none', !!user));
$$('[data-logout]').forEach(b => b.addEventListener('click', e => { e.preventDefault(); logout(); }));

/* ---------- Button helpers ---------- */
/* Shows a small spinner on a button for a moment, then runs the action */
function busy(btn, fn, ms = 450) {
  if (!btn || btn.disabled) return fn();
  const html = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>Please wait...';
  setTimeout(() => { btn.disabled = false; btn.innerHTML = html; fn(); }, ms);
}
/* Show / hide password buttons */
$$('[data-toggle-pass]').forEach(b => b.addEventListener('click', () => {
  const i = document.getElementById(b.dataset.togglePass), show = i.type === 'password';
  i.type = show ? 'text' : 'password';
  b.innerHTML = '<i class="bi bi-eye' + (show ? '-slash' : '') + '"></i>';
  b.setAttribute('aria-label', show ? 'Hide password' : 'Show password');
}));
/* Back to top button */
const topBtn = document.createElement('button');
topBtn.id = 'toTop'; topBtn.type = 'button'; topBtn.className = 'btn btn-brand';
topBtn.setAttribute('aria-label', 'Back to top'); topBtn.innerHTML = '<i class="bi bi-arrow-up"></i>';
document.body.appendChild(topBtn);
topBtn.addEventListener('click', () => window.scrollTo({ top: 0, behavior: 'smooth' }));
window.addEventListener('scroll', () => topBtn.classList.toggle('show', window.scrollY > 400), { passive: true });
/* Highlight the navbar link of the section you are reading (home page) */
if (PAGE === 'home') {
  const links = $$('#mainNav .nav-link[href^="#"]:not([href="#"])'), secs = links.map(a => $(a.getAttribute('href'))).filter(Boolean);
  const spy = () => {
    let cur = null; const y = window.scrollY + 120;
    secs.forEach(sec => { if (sec.offsetTop <= y) cur = sec.id; });
    $$('#mainNav .nav-link').forEach(a => { const h = a.getAttribute('href'); a.classList.toggle('active', h === '#' + cur || (!cur && h === 'index.html')); });
  };
  window.addEventListener('scroll', spy, { passive: true }); spy();
}

/* ---------- Clickable arrows: accordion + dropdown (own code, works with or without Bootstrap JS) ---------- */
function closeMenus(except) {
  $$('.dropdown-menu.show').forEach(m => {
    if (m === except) return;
    m.classList.remove('show');
    const t = m.parentElement.querySelector('[data-dd]');
    if (t) { t.classList.remove('show'); t.setAttribute('aria-expanded', 'false'); }
  });
}
document.addEventListener('click', e => {
  /* Accordion arrows (Who benefits? / Limitations) */
  const acc = e.target.closest('[data-acc]');
  if (acc) {
    const panel = $(acc.dataset.acc), open = !panel.classList.contains('show'), group = acc.closest('.accordion');
    if (group) group.querySelectorAll('[data-acc]').forEach(b => {
      const pn = $(b.dataset.acc);
      pn.classList.remove('show'); b.classList.add('collapsed'); b.setAttribute('aria-expanded', 'false');
    });
    panel.classList.toggle('show', open);
    acc.classList.toggle('collapsed', !open);
    acc.setAttribute('aria-expanded', open);
  }
  /* Profile dropdown arrow */
  const dd = e.target.closest('[data-dd]');
  const menu = dd ? dd.parentElement.querySelector('.dropdown-menu') : null;
  closeMenus(menu);
  if (dd && menu) {
    e.preventDefault();
    const open = !menu.classList.contains('show');
    menu.classList.toggle('show', open); dd.classList.toggle('show', open); dd.setAttribute('aria-expanded', open);
  }
  /* Switch to a saved account (asks for that account's password) */
  const sw = e.target.closest('[data-switch]');
  if (sw) {
    e.preventDefault();
    if (user && sw.dataset.switch === user.email) return closeMenus();
    S.del('ss_sess'); L.del('ss_sess');
    location.href = ROOT + 'pages/login.html?email=' + encodeURIComponent(sw.dataset.switch);
  }
});
document.addEventListener('keydown', e => { if (e.key === 'Escape') closeMenus(); });

/* ---------- Saved accounts list (stays until the account is deleted) ---------- */
function renderAccounts() {
  const users = L.get('ss_users', {}), emails = Object.keys(users);
  $$('.acctBox').forEach(box => {
    box.innerHTML = '<h6 class="dropdown-header">Saved accounts (' + emails.length + ')</h6>' +
      emails.map(em => {
        const u = users[em], cur = user && user.email === em;
        return '<a href="#" class="dropdown-item d-flex align-items-center gap-2' + (cur ? ' active-acct' : '') + '" data-switch="' + esc(em) + '">' +
          '<span class="avatar-sm">' + esc(u.name.trim().charAt(0).toUpperCase() || '?') + '</span>' +
          '<span class="flex-grow-1 lh-sm"><span class="d-block fw-semibold">' + esc(u.name) + '</span><small class="text-muted">' + esc(em) + '</small></span>' +
          (cur ? '<i class="bi bi-check-circle-fill text-success" title="Signed in"></i>' : '') + '</a>';
      }).join('') +
      '<a href="' + ROOT + 'pages/signup.html" class="dropdown-item"><i class="bi bi-person-plus me-2"></i>Add another account</a>';
  });
}
renderAccounts();

/* ---------- Sign up ---------- */
if (PAGE === 'signup') {
  if (user) goDash();
  $('#signForm').addEventListener('submit', e => {
    e.preventDefault();
    const n = $('#sName').value.trim(), em = $('#sEmail').value.trim().toLowerCase(), p = $('#sPass').value, p2 = $('#sPass2').value;
    if (!n || !/^\S+@\S+\.\S+$/.test(em)) return msg('danger', 'Enter your name and a valid email.');
    if (p.length < 6) return msg('danger', 'Password must be at least 6 characters.');
    if (p !== p2) return msg('danger', 'Passwords do not match.');
    const users = L.get('ss_users', {});
    if (users[em]) return msg('danger', 'That email is already registered. Please log in.');
    users[em] = { name: n, pw: hash(em + p) };
    L.set('ss_users', users);
    L.set('ss_sess', { email: em, name: n });
    busy(e.target.querySelector('button[type=submit]'), goDash, 350);
  });
}

/* ---------- Login ---------- */
if (PAGE === 'login') {
  if (user) goDash();
  if (new URLSearchParams(location.search).get('need')) msg('info', 'Please log in to open the dashboard.');
  const pre = new URLSearchParams(location.search).get('email');
  if (pre) { $('#lEmail').value = pre; $('#lPass').focus(); msg('info', 'Enter the password for ' + pre + '.'); }
  $('#loginForm').addEventListener('submit', e => {
    e.preventDefault();
    const em = $('#lEmail').value.trim().toLowerCase(), p = $('#lPass').value, u = L.get('ss_users', {})[em];
    if (!u || u.pw !== hash(em + p)) return msg('danger', 'Incorrect email or password.');
    (($('#remember') && $('#remember').checked) ? L : S).set('ss_sess', { email: em, name: u.name });
    busy(e.target.querySelector('button[type=submit]'), goDash, 350);
  });
}

/* ---------- Dashboard (all five pages + route, one view at a time) ---------- */
if (PAGE === 'dash') {
  if (!user) location.replace(ROOT + 'pages/login.html?need=1');
  else initApp(user);
}
function initApp(user) {
const db = L, AK = 'ss_alerts_' + user.email, EVK = 'ss_evals_' + user.email;
/* ---------- View switching ---------- */
function showView(v){
  if(!$('#v-'+v))v='home';
  $$('.view').forEach(e=>e.classList.toggle('on',e.id==='v-'+v));
  $$('.sidebar .nav-link[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));
  try{const o=bootstrap.Offcanvas.getInstance($('#mobileMenu'));if(o)o.hide()}catch(e){}
  window.scrollTo(0,0);
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b){e.preventDefault();showView(b.dataset.view)}});
const ROUTE_URL="https://www.google.com/maps/dir/?api=1&destination=University%20of%20Science%20and%20Technology%20of%20Southern%20Philippines%2C%20Cagayan%20de%20Oro";
$('#btnCopyRoute').addEventListener('click',()=>{
  const done=()=>{toast('Route link copied','success');const b=$('#btnCopyRoute');b.innerHTML='<i class="bi bi-clipboard-check"></i> Copied!';setTimeout(()=>b.innerHTML='<i class="bi bi-clipboard"></i> Copy Link',1800)};
  try{navigator.clipboard.writeText(ROUTE_URL).then(done,()=>toast('Copy not available. Use Open Location & Route.','warning'))}catch(e){toast('Copy not available. Use Open Location & Route.','warning')}
});
$$('[data-delete]').forEach(b=>b.addEventListener('click',e=>{
  e.preventDefault();
  if(!confirm('Delete your account and all saved data on this device?'))return;
  const u=L.get('ss_users',{});delete u[user.email];L.set('ss_users',u);L.del(AK);L.del(EVK);logout();
}));
$$('.uName').forEach(e=>e.textContent=user.name.split(' ')[0]);
$$('.uFull').forEach(e=>e.textContent=user.name);
$$('.uMail').forEach(e=>e.textContent=user.email);

/* ---------- Weather + risk engine ---------- */
const PRE={
  rain:{name:'Heavy Rainfall',t:27,r:35,l:false,h:92,icon:'bi-cloud-rain-heavy'},
  storm:{name:'Thunderstorm',t:28,r:20,l:true,h:90,icon:'bi-cloud-lightning-rain'},
  heat:{name:'Extreme Heat',t:41,r:0,l:false,h:60,icon:'bi-thermometer-sun'},
  clear:{name:'Clear Weather',t:30,r:0,l:false,h:62,icon:'bi-sun'}
};
let cur={...PRE.clear,loc:'My school route'};
function derive(c){
  const hum=c.h!=null?c.h:(c.r>0?90:60);
  const feels=Math.round(c.t+(c.t>=27?Math.max(0,hum-40)*0.06:0));
  const wind=c.l?45:c.r>=15?30:c.r>0?18:12;
  return {...c,hum,feels,wind};
}
function score(c,trav,min,el){
  let s=0,r=c.r;
  s+=r>=30?50:r>=15?35:r>=7.5?22:r>=2.5?10:r>0?5:0;
  if(c.l)s+=30;
  s+=c.feels>=41?45:c.feels>=36?30:c.feels>=32?12:0;
  s+=[10,20,0][trav];
  s+=min>30?15:min>10?8:3;
  if(el&&(r>0||c.l))s+=5;
  return Math.min(100,s);
}
const LV=s=>s>=70?['High','danger','Review your travel plan and prepare carefully.']:s>=40?['Moderate','warning','Prepare the items relevant to your trip.']:['Low','success','Conditions are favorable. Keep checking for changes.'];
function recs(c,trav,min,el){
  const a=[];
  if(c.r>=15)a.push(['bi-umbrella','Bring a raincoat or umbrella and put your bag and books in waterproof covers.'],['bi-water','Avoid flooded roads and never cross floodwater. Leave earlier because traffic and delays are likely.']);
  else if(c.r>0)a.push(['bi-umbrella','Light rain expected. Bring an umbrella or raincoat.']);
  if(c.l)a.push(['bi-lightning-charge','Lightning risk: stay away from open areas, tall trees and metal poles.'],['bi-house-door','If thunder is close, wait indoors and resume travel only after it has passed.']);
  if(c.feels>=36)a.push(['bi-cup-straw','Drink water before and during your trip to prevent dehydration.'],['bi-sunglasses','Wear light, loose clothing and use a hat or umbrella for shade.'],['bi-heart-pulse','Avoid long sun exposure and rest in the shade if you feel dizzy or weak.']);
  else if(c.feels>=32)a.push(['bi-cup-straw','It is hot. Bring drinking water and avoid staying under the sun for long.']);
  a.push([['bi-person-walking','Walking: use safe, covered routes and avoid slippery or flooded areas.'],['bi-bicycle','Bicycle/motorcycle: wet roads reduce traction and visibility. Avoid riding in heavy rain or lightning.'],['bi-bus-front','Covered transport: allow extra time for possible traffic and follow travel advisories.']][trav]);
  if(min>30)a.push(['bi-clock-history','Long trip ('+min+' min): you will be exposed longer. Prepare protective items and check conditions along the route.']);
  if(el&&(c.r>0||c.l))a.push(['bi-phone','Keep phone, tablet or laptop inside a waterproof pouch or bag.']);
  if(!c.r&&!c.l&&c.feels<32)a.push(['bi-check-circle','No major weather hazard right now. Still check the latest forecast before leaving.']);
  a.push(['bi-shield-check','Follow school announcements and official government advisories.']);
  return a;
}
function outlook(c){
  const base=c.l?85:c.r>=15?80:c.r>0?55:15,cl=v=>Math.max(0,Math.min(100,v));
  return [['Morning',c.t,cl(base)],['Afternoon',c.t+(c.r>0?1:2),cl(base+(c.r>0?-10:10))],['Evening',c.t-2,cl(base-15)]];
}
function analyze(push){
  const c=derive(cur),trav=+$('#tTrav').value,min=Math.max(1,Math.min(180,+$('#tMin').value||1)),el=$('#tEl').checked;
  const s=score(c,trav,min,el),lv=LV(s);
  $('#rTitle').innerHTML='<i class="bi '+(c.icon||'bi-cloud-sun')+' text-brand"></i> '+esc(c.name);
  $('#rLoc').textContent='Location: '+c.loc;
  $('#rBadge').className='badge fs-6 text-bg-'+lv[1];$('#rBadge').textContent=lv[0].toUpperCase()+' RISK';
  $('#sT').textContent=c.t+'\u00B0C';$('#sR').textContent=c.r+' mm/h';$('#sF').textContent=c.feels+'\u00B0C';$('#sW').textContent=c.wind+' km/h';
  $('#rScore').textContent=s;$('#rScore').className='score-big text-'+lv[1];
  $('#rBar').style.width=s+'%';$('#rBar').className='progress-bar bg-'+lv[1];$('#rMsg').textContent=lv[2];
  $('#routeTip').innerHTML='<i class="bi bi-info-circle me-1"></i>'+({Low:'Risk is Low. Take your usual route.',Moderate:'Risk is Moderate. Check the route for flooded or slippery areas and allow extra travel time.',High:'Risk is High. Review your route, avoid flooded or exposed roads and consider delaying travel.'})[lv[0]];
  $('#fc').innerHTML=outlook(c).map(f=>'<div class="col-4"><div class="border rounded p-2 text-center small"><div class="text-muted">'+f[0]+'</div><div class="fw-bold">'+f[1]+'\u00B0C</div><div class="text-primary">'+f[2]+'% rain</div></div></div>').join('')+'<div class="col-12 small text-muted">Simulated outlook for upcoming hours.</div>';
  $('#rRecs').innerHTML=recs(c,trav,min,el).map(r=>'<li class="d-flex gap-2 mb-2"><i class="bi '+r[0]+' text-brand fs-5"></i><span>'+esc(r[1])+'</span></li>').join('');
  if(push&&lv[0]!=='Low'){addAlert({lvl:lv[0],title:c.name+' risk at '+c.loc,msg:'Risk score '+s+'/100. '+lv[2]});toast('Alert added to the Alerts Center','warning')}
  return s;
}
$$('.preset').forEach(b=>b.addEventListener('click',()=>{
  const p=PRE[b.dataset.p];cur={...p,loc:$('#cLoc').value.trim()||'My school route'};
  $('#cT').value=p.t;$('#cR').value=p.r;$('#cL').checked=p.l;
  $$('.preset').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});
  analyze(true);
}));
$('#btnCustom').addEventListener('click',()=>{
  const t=+$('#cT').value,r=+$('#cR').value;
  if(isNaN(t)||t<10||t>50||isNaN(r)||r<0||r>100)return toast('Enter temperature 10-50 \u00B0C and rainfall 0-100 mm/h.','danger');
  const l=$('#cL').checked;
  const name=l?'Thunderstorm (custom)':r>=15?'Heavy Rainfall (custom)':r>0?'Light Rain (custom)':t>=36?'Extreme Heat (custom)':'Custom Conditions';
  cur={name,t,r,l,h:null,loc:$('#cLoc').value.trim()||'My school route',icon:l?'bi-cloud-lightning-rain':r>0?'bi-cloud-rain':t>=36?'bi-thermometer-sun':'bi-cloud-sun'};
  $$('.preset').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed',false)});
  busy($('#btnCustom'),()=>analyze(true));
});
['#tTrav','#tMin','#tEl'].forEach(s=>$(s).addEventListener('change',()=>analyze(false)));

/* ---------- Alerts ---------- */
const TPL=[
 {lvl:'High',title:'Thunderstorm Warning',msg:'Lightning and strong winds expected along school routes. Delay travel if possible and stay indoors.'},
 {lvl:'High',title:'Heavy Rainfall Warning',msg:'Intense rainfall may cause flooding and traffic delays. Avoid flooded roads.'},
 {lvl:'High',title:'Extreme Heat Alert',msg:'Heat levels are dangerous. Limit sun exposure and drink water frequently.'},
 {lvl:'Moderate',title:'Rain Showers Expected',msg:'Rain is likely this afternoon. Bring an umbrella and protect electronics.'},
 {lvl:'Moderate',title:'Hot and Humid Conditions',msg:'It will feel hotter than the actual temperature. Wear light clothing and bring water.'},
 {lvl:'Moderate',title:'Possible Thunderstorm Later',msg:'Storm clouds may develop. Check for updates before going home.'},
 {lvl:'Low',title:'Cloudy with Light Drizzle',msg:'Minor rain possible. A light raincoat is enough.'},
 {lvl:'Low',title:'Fair Weather',msg:'Conditions are favorable for travelling to school. Keep checking for changes.'}
];
let alerts=db.get(AK,null),aFilter='All',aid=Date.now();
if(!alerts){alerts=[
 {id:1,lvl:'Moderate',title:'Rain Showers Expected',msg:'Rain is likely this afternoon. Bring an umbrella and protect electronics.',time:'Today, 6:30 AM',ack:false},
 {id:2,lvl:'High',title:'Thunderstorm Warning',msg:'Lightning and strong winds expected along school routes. Delay travel if possible and stay indoors.',time:'Today, 6:45 AM',ack:false},
 {id:3,lvl:'Low',title:'Fair Weather',msg:'Conditions are favorable for travelling to school. Keep checking for changes.',time:'Yesterday, 5:50 PM',ack:true}]}
function saveAlerts(){db.set(AK,alerts)}
function now(){return new Date().toLocaleString([], {month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}
function addAlert(a){alerts.unshift({id:++aid,time:now(),ack:false,...a});saveAlerts();renderAlerts()}
function renderAlerts(){
  const col={High:'danger',Moderate:'warning',Low:'success'},ic={High:'bi-exclamation-octagon-fill',Moderate:'bi-exclamation-triangle-fill',Low:'bi-info-circle-fill'};
  const list=alerts.filter(a=>aFilter==='All'||a.lvl===aFilter);
  $('#aList').innerHTML=list.length?list.map(a=>'<div class="card border-0 shadow-sm alert-item '+a.lvl+(a.ack?' acked':'')+' mb-3"><div class="card-body d-flex flex-wrap gap-3 align-items-center justify-content-between"><div class="d-flex gap-3"><i class="bi '+ic[a.lvl]+' text-'+col[a.lvl]+' fs-3"></i><div><div class="fw-bold">'+esc(a.title)+' <span class="badge text-bg-'+col[a.lvl]+'">'+a.lvl+'</span>'+(a.ack?' <span class="badge text-bg-secondary">Acknowledged</span>':'')+'</div><div>'+esc(a.msg)+'</div><div class="small text-muted">'+esc(a.time)+'</div></div></div>'+(a.ack?'':'<button class="btn btn-outline-success btn-sm" data-ack="'+a.id+'"><i class="bi bi-check2"></i> Acknowledge</button>')+'</div></div>').join('')
    :'<div class="text-center text-muted py-5"><i class="bi bi-bell-slash display-4"></i><p class="mt-2 mb-0">No alerts for this filter. Use "Simulate Incoming Alert".</p></div>';
  const n=alerts.filter(a=>!a.ack).length;
  $('#aTot').textContent=alerts.length;$('#aNew').textContent=n;$('#aAck').textContent=alerts.length-n;
  $$('.navBadge').forEach(b=>{b.textContent=n;b.style.display=n?'inline-block':'none'});
}
$('#aSim').addEventListener('click',()=>{const t=TPL[Math.floor(Math.random()*TPL.length)];addAlert({...t});toast('Incoming alert: '+t.title,t.lvl==='High'?'danger':t.lvl==='Moderate'?'warning':'success')});
$('#aAckAll').addEventListener('click',()=>{alerts.forEach(a=>a.ack=true);saveAlerts();renderAlerts();toast('All alerts acknowledged','success')});
$('#aClear').addEventListener('click',()=>{if(confirm('Remove all alerts?')){alerts=[];saveAlerts();renderAlerts()}});
$('#aList').addEventListener('click',e=>{const b=e.target.closest('[data-ack]');if(!b)return;const a=alerts.find(x=>x.id==b.dataset.ack);if(a){a.ack=true;saveAlerts();renderAlerts()}});
$('#aFilters').addEventListener('click',e=>{const b=e.target.closest('[data-f]');if(!b)return;aFilter=b.dataset.f;$$('#aFilters .pill-btn').forEach(x=>x.classList.toggle('active',x===b));renderAlerts()});

/* ---------- About the Study ---------- */
const OBJ=['Develop an AI-assisted system that analyzes available weather data to identify potential risks associated with heavy rainfall, thunderstorms and extreme heat.','Create a risk classification feature that categorizes weather-related risks into appropriate levels, such as low, moderate and high.','Develop a feature that provides personalized weather alerts and preparation recommendations to help students respond to different weather conditions.','Provide weather risk information and preparedness recommendations to help students improve their awareness of possible weather-related risks before travelling to school.','Evaluate the functionality and usability of SKYSHIELD AI to determine its effectiveness and ease of use for students.'];
$('#objList').innerHTML=OBJ.map((o,i)=>'<div class="col-md-6"><div class="card border-0 shadow-sm h-100 card-hover"><div class="card-body d-flex gap-3"><span class="feature-icon flex-shrink-0 fw-bold">'+(i+1)+'</span><div><div class="fw-bold">Specific Objective '+(i+1)+'</div><div class="text-muted">'+o+'</div></div></div></div></div>').join('');
const SIG={
 'Students':['bi-mortarboard','This study will help students become more aware of possible weather-related risks by providing timely weather updates, risk information and personalized preparedness recommendations. It will also help them make informed decisions regarding their safety.'],
 'Teachers':['bi-person-workspace','This system may help teachers provide students with weather-related safety information and reminders, especially during severe weather conditions that may affect school activities.'],
 'School Administrators':['bi-building','The study may serve as an additional tool for improving school preparedness and awareness of weather-related risks. It may also support decision-making regarding student safety during unfavorable weather conditions.'],
 'Parents and Guardians':['bi-people','This system may help parents and guardians stay informed about possible weather risks that could affect their children\'s safety and daily activities.'],
 'Future Researchers':['bi-search','This study may serve as a reference for future researchers who wish to develop or improve systems involving artificial intelligence, weather risk prediction, disaster preparedness and student safety.']};
$('#sigBtns').innerHTML=['All',...Object.keys(SIG)].map((k,i)=>'<button class="btn btn-outline-secondary pill-btn'+(i?'':' active')+'" data-s="'+k+'">'+k+'</button>').join('');
function sigShow(k){$('#sigOut').innerHTML='<div class="row g-3">'+Object.entries(SIG).filter(([n])=>k==='All'||n===k).map(([n,v])=>'<div class="'+(k==='All'?'col-md-6':'col-lg-8 mx-auto')+'"><div class="card border-0 shadow-sm h-100"><div class="card-body p-4"><span class="feature-icon mb-3"><i class="bi '+v[0]+'"></i></span><h5 class="fw-bold">'+n+'</h5><p class="text-muted mb-0">'+v[1]+'</p></div></div></div>').join('')+'</div>'}
$('#sigBtns').addEventListener('click',e=>{const b=e.target.closest('[data-s]');if(!b)return;$$('#sigBtns .pill-btn').forEach(x=>x.classList.toggle('active',x===b));sigShow(b.dataset.s)});sigShow('All');
const SCOPE=[['Weather Information Monitoring','Provides students with current weather conditions and available upcoming forecasts to help them stay informed about changes in the weather.'],['AI-Assisted Weather Risk Prediction','Analyzes available weather data to identify possible weather-related risks and determine their corresponding risk levels.'],['Weather Risk Classification','Categorizes identified weather risks into three levels: low, moderate and high, so students understand the possible severity.'],['Personalized Preparedness Recommendations','Provides practical safety tips and preparation guidelines based on the identified conditions and risk levels.'],['Weather Alerts and Notifications','Provides alerts and important weather updates to inform students about possible weather threats.'],['Student-Friendly Interface','Offers an accessible and easy-to-use platform to view weather information, risk classifications, alerts and recommendations.']];
const LIM=[['Internet Connection Dependency','The system requires an internet connection to access weather information, update forecasts and deliver notifications. Without a stable connection, some features may not function properly.'],['Weather Data Accuracy','The accuracy of risk assessments depends on the availability, quality and reliability of weather data from external sources.'],['Prediction Limitations','The system cannot guarantee completely accurate predictions because weather conditions may change unexpectedly.'],['Limited Weather Coverage','Availability of weather information and risk assessments depends on the locations supported by the selected weather data sources.'],['Notification Dependency','Students may not receive alerts immediately due to poor connectivity, device settings or notification restrictions.'],['System Performance Limitations','Performance may depend on the capabilities of the devices used and the availability of required services.'],['Not a Replacement for Official Warnings','SKYSHIELD AI is only a supplementary preparedness tool. It should not replace official weather advisories, emergency announcements or safety instructions from authorized government agencies.']];
const card=(x,i,c)=>'<div class="card border-0 shadow-sm mb-3"><div class="card-body"><div class="fw-bold text-'+c+'">'+(i+1)+'. '+x[0]+'</div><div class="text-muted small">'+x[1]+'</div></div></div>';
$('#scopeList').innerHTML=SCOPE.map((x,i)=>card(x,i,'success')).join('');
$('#limList').innerHTML=LIM.map((x,i)=>card(x,i,'warning')).join('');
$('#aboutTabs').addEventListener('click',e=>{const b=e.target.closest('[data-t]');if(!b)return;$$('#aboutTabs .pill-btn').forEach(x=>x.classList.toggle('active',x===b));$$('.tab-pane-x').forEach(p=>p.hidden=p.id!=='t-'+b.dataset.t)});

/* ---------- Literature ---------- */
const LIT=[
{k:'Local',a:'Velasco et al.',y:2022,t:'Rainfall Forecasting Using Support Vector Regression Machines',s:'Used Support Vector Regression Machines on historical rainfall data from an automated rain gauge in Southern Philippines (four years and seventeen months of observations). The selected model reached a Mean Squared Error of 3.461315. Results show SVRM can become a useful rainfall forecasting method when data preparation, model parameters and time intervals are well chosen.',r:'Shows machine learning can forecast rainfall in a Philippine setting and gives a local foundation for data-driven rainfall risk identification.',ref:'Velasco, L. C., Aca-ac, J. M., Cajes, J. J., Lactuan, N. J., & Chit, S. C. (2022). Rainfall forecasting using support vector regression machines. International Journal of Advanced Computer Science and Applications, 13(3). https://doi.org/10.14569/IJACSA.2022.0130329'},
{k:'Local',a:'Baltazar et al.',y:2024,t:'The Role of Artificial Intelligence in Disaster Prediction, Mitigation, and Response in the Philippines',s:'A qualitative study with interviews of disaster-management officials, meteorologists and researchers. Machine learning and neural networks can process meteorological, seismic and geographical data to support forecasts and early warning. Challenges include limited infrastructure, budget constraints and data-quality problems.',r:'Supports AI for disaster-risk assessment and early warning, and stresses reliable data and suitable technology.',ref:'Baltazar, R., Florencio, B., Vicente, A., & Belizario, P. (2024). The role of artificial intelligence in disaster prediction, mitigation, and response in the Philippines: Challenges and opportunities. International Journal of Artificial Intelligence, 11(1), 37-51. https://doi.org/10.36079/lamintang.ijai-01101.675'},
{k:'Local',a:'GSMA',y:2022,t:'Early Warning Systems in the Philippines: Building Resilience Through Mobile and Digital Technologies',s:'Describes how mobile and digital technologies strengthen early warning systems through risk knowledge, forecasting and warning, dissemination and communication, and preparedness and response.',r:'Supports a digital platform that communicates weather risks and preparedness information in a way users can access and understand.',ref:'GSMA. (2022, June 17). Early warning systems in the Philippines: Building resilience through mobile and digital technologies. https://www.gsma.com/solutions-and-impact/connectivity-for-good/mobile-for-development/gsma_resources/ews-philippines-mobile-and-digital-technologies/'},
{k:'Local',a:'Vidal & Dela Cruz',y:2025,t:'Uncovering Students\u2019 Understanding on Climate Change, Vulnerability, and Disaster Risk Management',s:'Surveyed 522 students in selected secondary schools in the Philippines about climate-related risks and disaster management. The study proposed a climate-education program with a digital platform for interactive learning and real-time updates to improve climate literacy and preparedness.',r:'Directly supports the student-centered purpose of SKYSHIELD AI and the need for accessible digital tools.',ref:'Vidal, J., & Dela Cruz, R. R. (2025). Uncovering students\u2019 understanding on climate change, vulnerability, and disaster risk management among selected secondary schools in the Philippines. In Proceedings of the Asia Pacific Sociological Association Conference 2024 (pp. 295-302). Atlantis Press. https://doi.org/10.2991/978-94-6463-680-2_25'},
{k:'Foreign',a:'Kumar & Bassill',y:2025,t:'Artificial Intelligence and Machine Learning for Climate Disaster Management',s:'Explains how AI and machine learning can process satellite, weather-station and geospatial data to support disaster prediction, risk assessment, vulnerability mapping and early warning, as well as preparedness, response and recovery.',r:'Provides the technological foundation for analyzing weather information and giving timely preparedness guidance.',ref:'Kumar, D., & Bassill, N. P. (2025). Artificial intelligence and machine learning for climate disaster management. In Artificial intelligence and machine learning for climate disaster management (pp. 1-41). Springer Nature Singapore. https://doi.org/10.1007/978-981-95-1588-2_1'},
{k:'Foreign',a:'Aldous & Ismail',y:2025,t:'AI for Sustainable Emergency Preparedness and Response in Schools',s:'Examines how AI can improve emergency preparedness in schools through risk assessment, real-time monitoring, predictive capabilities and customized preparedness support, helping schools anticipate threats.',r:'Focuses on AI for school emergency preparedness and supports a student-oriented system with weather-risk information and recommendations.',ref:'Aldous, S. M., & Ismail, G. A. (2025). AI for sustainable emergency preparedness and response in schools. In Convergence of AI, education, and business for sustainability. IGI Global. https://doi.org/10.4018/979-8-3373-1917-9.ch003'},
{k:'Foreign',a:'Patel et al.',y:2023,t:'Disaster Preparedness and Awareness Among University Students: A Structural Equation Analysis',s:'Collected 111 responses from university students and used structural equation modeling. University curricula influenced students\u2019 disaster awareness, while established university emergency procedures influenced their preparedness.',r:'Emphasizes treating students as a specific group and tailoring recommendations to their needs and awareness levels.',ref:'Patel, R. K., Pamidimukkala, A., Kermanshachi, S., & Etminani-Ghasrodashti, R. (2023). Disaster preparedness and awareness among university students: A structural equation analysis. International Journal of Environmental Research and Public Health, 20(5), Article 4447. https://doi.org/10.3390/ijerph20054447'},
{k:'Foreign',a:'Iizuka',y:2022,t:'Disaster Perception and Preparation Among Foreign Versus Local University Students in Japan',s:'Questionnaire survey of 133 foreign and 150 Japanese students. Groups differed in disaster knowledge, concerns and preparedness: international students knew less about certain disasters, while Japanese students showed greater concern but were less prepared in some areas.',r:'Shows students differ in knowledge and preparedness, supporting clear, user-relevant information rather than only general warnings.',ref:'Iizuka, A. (2022). Disaster perception and preparation among foreign versus local university students in Japan: A comparative study. Progress in Disaster Science, 15, Article 100239. https://doi.org/10.1016/j.pdisas.2022.100239'},
{k:'Foreign',a:'Majumdar et al.',y:2024,t:'Bringing the Value Chain for High-Impact Weather Warnings into the Classroom',s:'Discusses how university students can learn the complete weather-warning process using the World Meteorological Organization\u2019s value-chain approach: observations, forecasting, hazards, impacts, warning communication and public responses. Students can also contribute information that helps researchers evaluate weather-warning effectiveness.',r:'',ref:'Majumdar, S. J., Hoffmann, D., Ebert, E. E., & Golding, B. W. (2024). Bringing the value chain for high-impact weather warnings into the classroom. Bulletin of the American Meteorological Society, 105, E1603-E1609. https://doi.org/10.1175/BAMS-D-23-0273.1'}];
let lf='All';
function renderLit(){
  const q=$('#litQ').value.trim().toLowerCase();
  const rows=LIT.map((x,i)=>({x,i})).filter(({x})=>(lf==='All'||x.k===lf)&&(!q||(x.a+' '+x.y+' '+x.t+' '+x.s+' '+x.k).toLowerCase().includes(q)));
  $('#litCount').textContent='Showing '+rows.length+' of '+LIT.length+' studies';
  $('#litList').innerHTML=rows.length?rows.map(({x,i})=>'<div class="col-lg-6"><div class="card border-0 shadow-sm h-100 card-hover"><div class="card-body p-4"><div class="d-flex justify-content-between mb-2"><span class="badge text-bg-'+(x.k==='Local'?'primary':'info')+'">'+x.k+' Literature</span><span class="text-muted small">'+x.y+'</span></div><h6 class="fw-bold">'+esc(x.a)+' ('+x.y+')</h6><p class="text-muted mb-2">'+esc(x.t)+'</p><button class="btn btn-outline-primary btn-sm" data-exp="'+i+'" aria-expanded="false"><i class="bi bi-chevron-down"></i> Read summary</button><div class="mt-3" id="ex'+i+'" hidden><div class="fw-semibold">Key findings</div><p class="small">'+esc(x.s)+'</p>'+(x.r?'<div class="fw-semibold">Relevance to SKYSHIELD AI</div><p class="small">'+esc(x.r)+'</p>':'')+'<div class="fw-semibold">Reference</div><p class="small text-muted mb-0">'+esc(x.ref)+'</p></div></div></div></div>').join('')
    :'<div class="col-12 text-center text-muted py-5"><i class="bi bi-search display-4"></i><p class="mt-2 mb-0">No studies match your search.</p></div>';
}
$('#litQ').addEventListener('input',renderLit);
$('#litF').addEventListener('click',e=>{const b=e.target.closest('[data-f]');if(!b)return;lf=b.dataset.f;$$('#litF .pill-btn').forEach(x=>x.classList.toggle('active',x===b));renderLit()});
$('#litList').addEventListener('click',e=>{const b=e.target.closest('[data-exp]');if(!b)return;const p=$('#ex'+b.dataset.exp),open=p.hidden;p.hidden=!open;b.setAttribute('aria-expanded',open);b.innerHTML=open?'<i class="bi bi-chevron-up"></i> Hide summary':'<i class="bi bi-chevron-down"></i> Read summary'});

/* ---------- Evaluation ---------- */
const FQ=['The weather information is displayed clearly and correctly.','The risk classification (Low, Moderate, High) works as expected.','The personalized recommendations are relevant to the weather condition.','The alerts and notifications are useful and easy to follow.','The system is reliable and responds correctly to my actions.'];
const UQ=['The system is easy to navigate.','The language and instructions are easy to understand.','The interface is attractive and student-friendly.','I can use the system without help.','I would use SKYSHIELD AI before travelling to school.'];
const SC=['Poor','Fair','Good','Very Good','Excellent'];
function qBlock(title,arr,p){return '<h6 class="fw-bold mt-2">'+title+'</h6>'+arr.map((q,i)=>'<div class="mb-3 rate"><div class="small mb-1">'+(i+1)+'. '+q+'</div><div class="btn-group w-100" role="group">'+[1,2,3,4,5].map(n=>'<input type="radio" class="btn-check" name="'+p+i+'" id="'+p+i+'_'+n+'" value="'+n+'"><label class="btn btn-outline-primary btn-sm" for="'+p+i+'_'+n+'" title="'+SC[n-1]+'">'+n+'</label>').join('')+'</div></div>').join('')}
$('#evQs').innerHTML=qBlock('A. Functionality',FQ,'f')+qBlock('B. Usability',UQ,'u');
const interp=v=>v>=4.5?['Excellent','success']:v>=3.5?['Very Good','primary']:v>=2.5?['Good','info']:v>=1.5?['Fair','warning']:['Poor','danger'];
const avg=a=>a.reduce((x,y)=>x+y,0)/a.length;
function renderAgg(){
  const ev=db.get(EVK,[]);
  $('#evAgg').innerHTML=ev.length?'<b>'+ev.length+'</b> response(s). Average functionality <b>'+avg(ev.map(e=>e.f)).toFixed(2)+'</b>, usability <b>'+avg(ev.map(e=>e.u)).toFixed(2)+'</b>, overall <b>'+interp(avg(ev.map(e=>e.o)))[0]+'</b>.':'No responses yet.';
}
$('#evForm').addEventListener('submit',e=>{
  e.preventDefault();
  const get=p=>FQ.map((_,i)=>{const c=document.querySelector('input[name="'+p+i+'"]:checked');return c?+c.value:null});
  const f=get('f'),u=UQ.map((_,i)=>{const c=document.querySelector('input[name="u'+i+'"]:checked');return c?+c.value:null});
  if(f.includes(null)||u.includes(null)){$('#evErr').innerHTML='<div class="alert alert-danger py-2">Please rate all 10 items before submitting.</div>';return}
  $('#evErr').innerHTML='';
  const fa=avg(f),ua=avg(u),oa=avg([...f,...u]),pct=Math.round(oa/5*100),ip=interp(oa);
  const ev=db.get(EVK,[]);ev.push({f:fa,u:ua,o:oa,who:$('#evWho').value});db.set(EVK,ev);
  const bar=(l,v)=>'<div class="mb-3"><div class="d-flex justify-content-between small"><span>'+l+'</span><b>'+v.toFixed(2)+' / 5</b></div><div class="progress" style="height:10px"><div class="progress-bar" style="width:'+(v/5*100)+'%"></div></div></div>';
  $('#evOut').innerHTML='<h5 class="fw-bold mb-3"><i class="bi bi-clipboard-data text-brand"></i> Your Usability Score Summary</h5><div class="text-center mb-3"><div class="score-big text-'+ip[1]+'">'+pct+'%</div><span class="badge text-bg-'+ip[1]+' fs-6 mt-2">'+ip[0]+'</span></div>'+bar('Functionality',fa)+bar('Usability',ua)+bar('Overall',oa)+'<div class="small text-muted">Respondent: '+esc($('#evWho').value)+'. Scale: 1 Poor, 2 Fair, 3 Good, 4 Very Good, 5 Excellent.</div>';
  renderAgg();toast('Evaluation submitted. Thank you!','success');
});
$('#evReset').addEventListener('click',()=>{if(confirm('Delete all saved evaluation responses?')){db.del(EVK);renderAgg();$('#evOut').innerHTML='<div class="text-center text-muted py-4"><i class="bi bi-clipboard-data display-4"></i><p class="mt-2 mb-0">Submit the form to see your usability score summary.</p></div>';$('#evForm').reset()}});

/* ---------- Start ---------- */
renderAlerts();renderLit();renderAgg();
document.querySelector('.preset[data-p="clear"]').click();
showView('home');
/* Open a page from the link, e.g. dashboard.html#eval (Usability Survey) */
const startView = location.hash.slice(1);
if (startView && $('#v-' + startView)) showView(startView);
}
